import React from 'react';
import { BrowserRouter as Router, Routes, Route, Navigate } from 'react-router-dom';
import { ThemeProvider, createTheme } from '@mui/material/styles';
import CssBaseline from '@mui/material/CssBaseline';
import styled, { createGlobalStyle } from 'styled-components';
import RecipeApp from './components/RecipeApp';
import { HomePage } from './components/HomePage';
import { RecipeByIdPage } from './components/RecipeByIdPage';
import ErrorBoundary from './components/ErrorBoundary';

const theme = createTheme({
  palette: {
    primary: {
      main: '#ff6b6b',
      light: '#ff9999',
      dark: '#ff5252',
    },
    secondary: {
      main: '#4ecdc4',
      light: '#7fefef',
      dark: '#26a69a',
    },
    background: {
      default: '#f5f5f5',
      paper: '#ffffff',
    },
    text: {
      primary: '#333333',
      secondary: '#666666',
    },
  },
  typography: {
    fontFamily: [
      '-apple-system',
      'BlinkMacSystemFont',
      '"Segoe UI"',
      'Roboto',
      '"Helvetica Neue"',
      'Arial',
      'sans-serif',
    ].join(','),
    h4: {
      fontWeight: 700,
    },
    h5: {
      fontWeight: 600,
    },
    h6: {
      fontWeight: 600,
    },
  },
  shape: {
    borderRadius: 8,
  },
  components: {
    MuiButton: {
      styleOverrides: {
        root: {
          textTransform: 'none',
          borderRadius: 8,
          fontWeight: 600,
        },
      },
    },
    MuiCard: {
      styleOverrides: {
        root: {
          borderRadius: 12,
        },
      },
    },
  },
});

const GlobalStyle = createGlobalStyle`
  * {
    margin: 0;
    padding: 0;
    box-sizing: border-box;
  }

  body {
    font-family: ${theme.typography.fontFamily};
    -webkit-font-smoothing: antialiased;
    -moz-osx-font-smoothing: grayscale;
    background: ${theme.palette.background.default};
    line-height: 1.5;
  }

  button {
    font-family: inherit;
  }

  #root {
    min-height: 100vh;
  }

  /* 스크롤바 스타일링 */
  ::-webkit-scrollbar {
    width: 6px;
  }

  ::-webkit-scrollbar-track {
    background: #f1f1f1;
  }

  ::-webkit-scrollbar-thumb {
    background: #c1c1c1;
    border-radius: 3px;
  }

  ::-webkit-scrollbar-thumb:hover {
    background: #a8a8a8;
  }
`;

const AppContainer = styled.div`
  min-height: 100vh;
  background: ${theme.palette.background.default};
`;

function App() {
  return (
    <ThemeProvider theme={theme}>
      <CssBaseline />
      <GlobalStyle />
      <ErrorBoundary>
        <AppContainer>
          <Router basename="/home">
            <Routes>
              {/* 홈페이지 */}
              <Route path="/" element={<HomePage />} />
              
              {/* 김치볶음밥 레시피 페이지 (간단한 경로) */}
              <Route path="/kimchi-fried-rice" element={<RecipeByIdPage />} />
              
              {/* UUID 기반 레시피 페이지 (기존 호환성) */}
              <Route path="/recipe/:recipeId" element={<RecipeByIdPage />} />
              
              {/* 기존 레시피 앱 */}
              <Route path="/app" element={<RecipeApp />} />
              
              {/* 기존 경로들을 김치볶음밥으로 리다이렉트 */}
              <Route path="/viewer" element={<Navigate to="/kimchi-fried-rice" replace />} />
              
              {/* 404 페이지 */}
              <Route path="*" element={<Navigate to="/" replace />} />
            </Routes>
          </Router>
        </AppContainer>
      </ErrorBoundary>
    </ThemeProvider>
  );
}

export default App;
