import { Recipe } from '../types/Recipe';
import { mockRecipe } from '../data/mockData';

export interface RecipeAnalysisRequest {
  url: string;
  options?: {
    language?: 'ko' | 'en';
    servings?: number;
    extractIngredients?: boolean;
  };
}

export interface RecipeAnalysisResponse {
  success: boolean;
  data?: Recipe;
  error?: string;
  processingTime?: number;
}

export interface AnalysisProgress {
  step: 'downloading' | 'analyzing' | 'extracting' | 'generating' | 'completed';
  progress: number; // 0-100
  message: string;
}

class RecipeService {
  private baseUrl = process.env.REACT_APP_API_BASE_URL || 'http://localhost:8080/api';
  private isDevelopment = process.env.NODE_ENV === 'development';

  /**
   * URL에서 레시피를 분석하여 단계별 레시피로 변환
   */
  async analyzeRecipeFromUrl(
    request: RecipeAnalysisRequest,
    onProgress?: (progress: AnalysisProgress) => void
  ): Promise<RecipeAnalysisResponse> {
    try {
      // 개발 환경에서 API 서버 연결 확인
      if (this.isDevelopment) {
        const isServerAvailable = await this.checkServerHealth();
        if (!isServerAvailable) {
          console.warn('API 서버에 연결할 수 없습니다. 목업 데이터를 사용합니다.');
          return this.getMockAnalysisResult(request, onProgress);
        }
      }

      // 실제 API 호출
      const response = await fetch(`${this.baseUrl}/recipes/analyze`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify(request),
        signal: AbortSignal.timeout(30000), // 30초 타임아웃
      });

      if (!response.ok) {
        throw new Error(`HTTP error! status: ${response.status}`);
      }

      // 실제 구현에서는 진행 상황을 실시간으로 받아옴
      if (onProgress) {
        const progressSteps: AnalysisProgress[] = [
          { step: 'downloading', progress: 20, message: '비디오 다운로드 중...' },
          { step: 'analyzing', progress: 40, message: '비디오 분석 중...' },
          { step: 'extracting', progress: 70, message: '레시피 단계 추출 중...' },
          { step: 'generating', progress: 90, message: '재료 정보 생성 중...' },
          { step: 'completed', progress: 100, message: '분석 완료!' },
        ];

        for (const step of progressSteps) {
          onProgress(step);
          await new Promise(resolve => setTimeout(resolve, 800));
        }
      }

      const data: RecipeAnalysisResponse = await response.json();
      return data;

    } catch (error) {
      console.error('Recipe analysis failed:', error);
      
      // 개발 환경에서는 목업 데이터로 대체
      if (this.isDevelopment) {
        console.warn('API 호출 실패, 목업 데이터로 대체합니다.');
        return this.getMockAnalysisResult(request, onProgress);
      }

      return {
        success: false,
        error: error instanceof Error ? error.message : '알 수 없는 오류가 발생했습니다.',
      };
    }
  }

  /**
   * 서버 상태 확인
   */
  private async checkServerHealth(): Promise<boolean> {
    try {
      const response = await fetch(`${this.baseUrl}/health`, {
        method: 'GET',
        signal: AbortSignal.timeout(3000), // 3초 타임아웃
      });
      return response.ok;
    } catch {
      return false;
    }
  }

  /**
   * 목업 분석 결과 반환 (개발용)
   */
  private async getMockAnalysisResult(
    request: RecipeAnalysisRequest,
    onProgress?: (progress: AnalysisProgress) => void
  ): Promise<RecipeAnalysisResponse> {
    // 진행 상황 시뮬레이션
    if (onProgress) {
      const progressSteps: AnalysisProgress[] = [
        { step: 'downloading', progress: 25, message: '비디오 다운로드 중...' },
        { step: 'analyzing', progress: 50, message: '비디오 분석 중...' },
        { step: 'extracting', progress: 75, message: '레시피 단계 추출 중...' },
        { step: 'generating', progress: 90, message: '재료 정보 생성 중...' },
        { step: 'completed', progress: 100, message: '분석 완료!' },
      ];

      for (const step of progressSteps) {
        onProgress(step);
        await new Promise(resolve => setTimeout(resolve, 600));
      }
    }

    // URL에 따라 다른 목업 데이터 반환 (실제로는 분석 결과)
    const mockData = {
      ...mockRecipe,
      id: `mock-${Date.now()}`,
      title: this.extractTitleFromUrl(request.url) || mockRecipe.title,
    };

    return {
      success: true,
      data: mockData,
      processingTime: 3000,
    };
  }

  /**
   * URL에서 제목 추출 (간단한 예시)
   */
  private extractTitleFromUrl(url: string): string | null {
    try {
      const urlObj = new URL(url);
      if (urlObj.hostname.includes('instagram')) return '인스타그램 레시피';
      if (urlObj.hostname.includes('youtube')) return '유튜브 레시피';
      if (urlObj.hostname.includes('tiktok')) return '틱톡 레시피';
      return null;
    } catch {
      return null;
    }
  }

  /**
   * 지원되는 플랫폼 확인
   */
  isSupportedUrl(url: string): boolean {
    const supportedDomains = [
      'instagram.com',
      'youtube.com',
      'youtu.be',
      'tiktok.com',
      'reels.instagram.com',
    ];

    try {
      const urlObj = new URL(url);
      return supportedDomains.some(domain => 
        urlObj.hostname.includes(domain)
      );
    } catch {
      return false;
    }
  }

  /**
   * URL 유효성 검사
   */
  validateUrl(url: string): { isValid: boolean; error?: string } {
    try {
      new URL(url);
      
      if (!this.isSupportedUrl(url)) {
        return {
          isValid: false,
          error: '지원되지 않는 플랫폼입니다. Instagram, YouTube, TikTok 링크를 사용해주세요.',
        };
      }

      return { isValid: true };
    } catch {
      return {
        isValid: false,
        error: '올바른 URL 형식이 아닙니다.',
      };
    }
  }

  /**
   * 레시피 저장 (선택사항)
   */
  async saveRecipe(recipe: Recipe): Promise<{ success: boolean; id?: string; error?: string }> {
    try {
      const response = await fetch(`${this.baseUrl}/recipes`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify(recipe),
      });

      if (!response.ok) {
        throw new Error(`HTTP error! status: ${response.status}`);
      }

      const data = await response.json();
      return { success: true, id: data.id };

    } catch (error) {
      return {
        success: false,
        error: error instanceof Error ? error.message : '레시피 저장에 실패했습니다.',
      };
    }
  }

  /**
   * 저장된 레시피 목록 조회
   */
  async getSavedRecipes(): Promise<{ success: boolean; recipes?: Recipe[]; error?: string }> {
    try {
      const response = await fetch(`${this.baseUrl}/recipes`);
      
      if (!response.ok) {
        throw new Error(`HTTP error! status: ${response.status}`);
      }

      const recipes: Recipe[] = await response.json();
      return { success: true, recipes };

    } catch (error) {
      return {
        success: false,
        error: error instanceof Error ? error.message : '레시피 목록을 불러올 수 없습니다.',
      };
    }
  }
}

export const recipeService = new RecipeService();
export default recipeService; 