import { useRef, useEffect, useState, useCallback } from 'react';

interface UseVideoPlayerProps {
  videoUrl: string;
  onNext: () => void;
  onPrev: () => void;
  canGoNext: boolean;
  canGoPrev: boolean;
}

interface UseVideoPlayerReturn {
  videoRef: React.RefObject<HTMLVideoElement | null>;
  isPlaying: boolean;
  progress: number;
  playbackRate: number;
  showSwipeIndicator: 'left' | 'right' | null;
  videoAspectRatio: string;
  deviceOrientation: 'portrait' | 'landscape';
  isFullscreen: boolean;
  togglePlay: () => void;
  toggleSpeed: () => void;
  toggleFullscreen: () => void;
  handleSwipeLeft: () => void;
  handleSwipeRight: () => void;
}

export const useVideoPlayer = ({
  videoUrl,
  onNext,
  onPrev,
  canGoNext,
  canGoPrev
}: UseVideoPlayerProps): UseVideoPlayerReturn => {
  const videoRef = useRef<HTMLVideoElement | null>(null);
  const [isPlaying, setIsPlaying] = useState(true);
  const [progress, setProgress] = useState(0);
  const [playbackRate, setPlaybackRate] = useState(1);
  const [showSwipeIndicator, setShowSwipeIndicator] = useState<'left' | 'right' | null>(null);
  const [videoAspectRatio, setVideoAspectRatio] = useState('9/16');
  const [deviceOrientation, setDeviceOrientation] = useState<'portrait' | 'landscape'>('portrait');
  const [isFullscreen, setIsFullscreen] = useState(false);

  // 디바이스 방향 감지
  useEffect(() => {
    const handleOrientationChange = () => {
      const orientation = window.screen?.orientation?.type || 
                         (window.innerWidth > window.innerHeight ? 'landscape-primary' : 'portrait-primary');
      setDeviceOrientation(orientation.includes('landscape') ? 'landscape' : 'portrait');
    };

    const handleResize = () => {
      handleOrientationChange();
    };

    // 초기 방향 설정
    handleOrientationChange();

    // 이벤트 리스너 등록
    window.addEventListener('orientationchange', handleOrientationChange);
    window.addEventListener('resize', handleResize);

    return () => {
      window.removeEventListener('orientationchange', handleOrientationChange);
      window.removeEventListener('resize', handleResize);
    };
  }, []);

  // 비디오 메타데이터 로드 시 화면비 계산
  useEffect(() => {
    const video = videoRef.current;
    if (!video) return;

    const handleLoadedMetadata = () => {
      const { videoWidth, videoHeight } = video;
      if (videoWidth && videoHeight) {
        const aspectRatio = videoWidth / videoHeight;
        
        // 화면비에 따른 CSS aspect-ratio 값 설정
        if (aspectRatio > 1.7) {
          setVideoAspectRatio('16/9'); // 가로 영상
        } else if (aspectRatio > 0.9 && aspectRatio < 1.1) {
          setVideoAspectRatio('1/1'); // 정사각형
        } else if (aspectRatio < 0.7) {
          setVideoAspectRatio('9/16'); // 세로 영상
        } else {
          setVideoAspectRatio(`${videoWidth}/${videoHeight}`); // 커스텀 비율
        }
      }
    };

    video.addEventListener('loadedmetadata', handleLoadedMetadata);
    return () => video.removeEventListener('loadedmetadata', handleLoadedMetadata);
  }, [videoUrl]);

  // 풀스크린 상태 감지
  useEffect(() => {
    const handleFullscreenChange = () => {
      setIsFullscreen(!!document.fullscreenElement);
    };

    document.addEventListener('fullscreenchange', handleFullscreenChange);
    return () => document.removeEventListener('fullscreenchange', handleFullscreenChange);
  }, []);

  // 비디오 이벤트 핸들러
  useEffect(() => {
    const video = videoRef.current;
    if (!video) return;

    const handleTimeUpdate = () => {
      const progress = (video.currentTime / video.duration) * 100;
      setProgress(progress);
    };

    const handleEnded = () => {
      setProgress(0);
      video.currentTime = 0;
      video.play(); // 자동 반복
    };

    const handleLoadedData = () => {
      video.play().catch(() => {
        setIsPlaying(false);
      });
    };

    video.addEventListener('timeupdate', handleTimeUpdate);
    video.addEventListener('ended', handleEnded);
    video.addEventListener('loadeddata', handleLoadedData);

    return () => {
      video.removeEventListener('timeupdate', handleTimeUpdate);
      video.removeEventListener('ended', handleEnded);
      video.removeEventListener('loadeddata', handleLoadedData);
    };
  }, [videoUrl]);

  // 재생/일시정지 토글
  const togglePlay = useCallback(() => {
    const video = videoRef.current;
    if (!video) return;

    if (isPlaying) {
      video.pause();
    } else {
      video.play();
    }
    setIsPlaying(!isPlaying);
  }, [isPlaying]);

  // 재생 속도 변경
  const toggleSpeed = useCallback(() => {
    const video = videoRef.current;
    if (!video) return;

    const speeds = [0.5, 1, 1.5, 2];
    const currentIndex = speeds.indexOf(playbackRate);
    const nextSpeed = speeds[(currentIndex + 1) % speeds.length];
    
    video.playbackRate = nextSpeed;
    setPlaybackRate(nextSpeed);
  }, [playbackRate]);

  // 풀스크린 토글
  const toggleFullscreen = useCallback(async () => {
    const video = videoRef.current;
    if (!video) return;

    try {
      if (!document.fullscreenElement) {
        await video.requestFullscreen();
      } else {
        await document.exitFullscreen();
      }
    } catch (error) {
      console.warn('Fullscreen not supported:', error);
    }
  }, []);

  // 스와이프 핸들러
  const handleSwipeLeft = useCallback(() => {
    if (canGoNext) {
      setShowSwipeIndicator('right');
      setTimeout(() => setShowSwipeIndicator(null), 300);
      onNext();
    }
  }, [canGoNext, onNext]);

  const handleSwipeRight = useCallback(() => {
    if (canGoPrev) {
      setShowSwipeIndicator('left');
      setTimeout(() => setShowSwipeIndicator(null), 300);
      onPrev();
    }
  }, [canGoPrev, onPrev]);

  return {
    videoRef,
    isPlaying,
    progress,
    playbackRate,
    showSwipeIndicator,
    videoAspectRatio,
    deviceOrientation,
    isFullscreen,
    togglePlay,
    toggleSpeed,
    toggleFullscreen,
    handleSwipeLeft,
    handleSwipeRight
  };
}; 