// GitHub Pages에서는 /home 경로가 기본이므로 PUBLIC_URL을 사용
const getVideoUrl = (filename: string) => {
  const publicUrl = process.env.PUBLIC_URL || '';
  return `${publicUrl}/videos/${filename}`;
};

